<script setup lang="ts">
import { computed, ref } from 'vue';
const props = defineProps<{ state: any; participants: any[]; isPlayer: boolean; myPlayerId?: string; isDemo: boolean }>();
const emit = defineEmits<{ action: [action: any] }>();
const selected = ref<string[]>([]);
const state = computed(() => props.state || {});
const cards = computed(() => state.value.ownCards || []);
const me = computed(() => (state.value.players || []).find((player: any) => player.playerId === props.myPlayerId));
const myTurn = computed(() => state.value.currentPlayer === props.myPlayerId);
const nameOf = (id: string) => props.participants.find((p: any) => p.id === id)?.display_name || props.participants.find((p: any) => p.id === id)?.username || id.slice(0, 8);
const toggle = (card: any) => { if (!myTurn.value) return; selected.value = selected.value.includes(card.cardId) ? selected.value.filter((id) => id !== card.cardId) : [...selected.value, card.cardId]; };
const act = (type: string) => { if (type === 'PLAY_CARDS' && !selected.value.length) return; emit('action', { type, ...(type === 'PLAY_CARDS' ? { cardIds: selected.value, actionId: `${props.myPlayerId}:${Date.now()}` } : { actionId: `${props.myPlayerId}:${type}:${Date.now()}` }) }); selected.value = []; };
const rankLabel = (rank: number) => rank === 1 ? 'A' : rank === 2 ? '2' : String(rank);
const suitSymbol: Record<string, string> = { SPADE: '♠', CLUB: '♣', DIAMOND: '♦', HEART: '♥' };
</script>
<template>
  <section class="tl-arena"><header class="tl-header"><div><span class="tl-kicker">LUNU CARD TABLE</span><h1>Tiến Lên Miền Nam</h1></div><div class="tl-status"><span :class="{ live: myTurn }">{{ myTurn ? 'YOUR TURN' : 'ĐANG CHỜ' }}</span><strong>{{ state.phase === 'ROUND_END' ? 'Ván kết thúc' : `Lượt ${state.turnNumber || 1}` }}</strong></div></header>
    <div class="tl-layout"><main class="tl-felt"><div class="tl-ring"></div><div class="tl-opponents"><article v-for="player in (state.players || []).filter((p: any) => p.playerId !== myPlayerId)" :key="player.playerId" :class="['tl-player', { finished: player.isFinished }]" ><span class="tl-avatar">{{ nameOf(player.playerId).slice(0,1).toUpperCase() }}</span><strong>{{ nameOf(player.playerId) }}</strong><small>{{ player.cardsCount ?? player.cards?.length ?? 0 }} lá · ghế {{ player.seat + 1 }}</small><b v-if="state.currentPlayer === player.playerId">LƯỢT</b></article></div><div class="tl-table-center"><div class="tl-last-label">{{ state.lastPlay ? `Bài của ${nameOf(state.lastPlay.playerId)}` : 'Chưa có lượt bài' }}</div><div class="tl-table-cards"><div v-for="card in (state.table || [])" :key="card.cardId" class="tl-card small" :class="card.suit === 'HEART' || card.suit === 'DIAMOND' ? 'red' : ''"><strong>{{ rankLabel(card.rank) }}</strong><span>{{ suitSymbol[card.suit] }}</span></div><div v-if="!(state.table || []).length" class="tl-empty">Đánh một bộ bài để bắt đầu</div></div><p class="tl-trick">{{ state.passCount || 0 }} người đã bỏ lượt · bàn sẽ reset khi hết vòng</p></div><div class="tl-my-seat"><span class="tl-avatar gold">{{ (nameOf(myPlayerId || 'B') || 'B').slice(0,1).toUpperCase() }}</span><strong>{{ nameOf(myPlayerId || 'Bạn') }}</strong><small>{{ me?.isFinished ? `Hạng ${me.rank}` : `${cards.length} lá trên tay` }}</small></div></main>
      <aside class="tl-side"><div class="tl-panel"><span class="tl-kicker">BÀI CỦA BẠN</span><div class="tl-hand"><button v-for="card in cards" :key="card.cardId" class="tl-card" :class="[{ selected: selected.includes(card.cardId) }, card.suit === 'HEART' || card.suit === 'DIAMOND' ? 'red' : '']" @click="toggle(card)"><strong>{{ rankLabel(card.rank) }}</strong><span>{{ suitSymbol[card.suit] }}</span></button></div><div class="tl-actions"><button class="primary" @click="act('PLAY_CARDS')" :disabled="!myTurn || !selected.length">Đánh {{ selected.length ? `${selected.length} lá` : 'bài' }}</button><button class="secondary" @click="act('PASS')" :disabled="!myTurn || !state.lastPlay">Bỏ lượt</button></div><p class="tl-hint">Luật được kiểm tra phía máy chủ. Client không quyết định tổ hợp hợp lệ.</p></div><div class="tl-panel tl-history"><span class="tl-kicker">LỊCH SỬ VÁN</span><p v-for="(event, index) in (state.eventLog || []).slice(-7).reverse()" :key="`${event.at}-${index}`"><b>{{ event.type.replaceAll('_', ' ') }}</b><small>{{ event.playerId ? nameOf(event.playerId) : '' }}</small></p></div></aside>
    </div>
  </section>
</template>
<style scoped>
