e:.61rem}.tl-history small{color:#8fa99a}@media(max-width:900px){.tl-layout{grid-template-columns:1fr}.tl-felt{min-height:620px}.tl-side{display:grid;grid-template-columns:1fr 1fr}}@media(max-width:600px){.tl-header{align-items:start;flex-direction:column;gap:15px}.tl-status{text-align:left}.tl-felt{padding:15px;border-width:7px}.tl-opponents{gap:5px}.tl-player{min-width:0;padding:7px}.tl-player strong{font-size:.58rem}.tl-player small{font-size:.48rem}.tl-side{display:flex}.tl-hand{justify-content:center}}
